-- 坂沢線（tokyo-sakasawa）の区間データ。tools/road.py build data/roads/tokyo-sakasawa.json で生成。手で編集しない。
-- schema.sql を実行したあとに、SQL Editor で全文を実行する。何度実行しても同じ状態になる。
-- 出典：線：© OpenStreetMap contributors（ODbL）
-- 出典：通行可否と規制：東京都森林事務所「森林事務所管理林道の通行規制について」通行状況一覧（令和8年10月2日現在）。「通行規制」は林業関係者以外の車両の乗り入れを規制。data/sources/tokyo-forestry-2026-10-02.tsv

set search_path = public, extensions;

insert into administrators (name, kind) values ('東京都森林事務所 秋川林務出張所', '都')
on conflict (name) do nothing;
insert into roads (name, kind) values ('坂沢線', '林道')
on conflict (name) do nothing;

delete from segments where road_id = (select id from roads where name = '坂沢線');

-- あきる野市：通行規制、起点に柵有。林業関係者以外の車両は乗り入れ不可（約0.8km）
insert into segments (road_id, administrator_id, surface, difficulty, general_access, note, geom)
select r.id, a.id, null, null, '不可', 'あきる野市：通行規制、起点に柵有。林業関係者以外の車両は乗り入れ不可',
  ST_SetSRID(ST_GeomFromGeoJSON('{"type":"LineString","coordinates":[[139.2085022,35.721911],[139.2087484,35.7217023],[139.2088057,35.7217089],[139.2089206,35.7216982],[139.2090387,35.7216931],[139.2091594,35.7217119],[139.2093066,35.7217267],[139.2094253,35.7217244],[139.2095019,35.7217081],[139.2095541,35.7216685],[139.2095816,35.7216236],[139.2095644,35.7215587],[139.2095326,35.7214982],[139.20949,35.7213927],[139.209468,35.7212686],[139.2094558,35.7211406],[139.2094433,35.7209401],[139.209439,35.7208699],[139.2094667,35.7208041],[139.2095049,35.7207445],[139.209595,35.7206619],[139.2096829,35.7206197],[139.2097754,35.7206044],[139.2098876,35.7206112],[139.2099482,35.7206105],[139.2101043,35.7205647],[139.2101931,35.7205039],[139.210243,35.7204473],[139.2102775,35.7204008],[139.2103166,35.720327],[139.210331,35.7202532],[139.2103703,35.7202017],[139.2104287,35.7201597],[139.2105055,35.7201327],[139.2106223,35.7200987],[139.2107096,35.7201126],[139.210918,35.7201832],[139.211108,35.7202437],[139.2111619,35.7202566],[139.2112372,35.7202717],[139.2113124,35.7202729],[139.2113951,35.7202504],[139.2114557,35.7202279],[139.2115049,35.7201776],[139.2115942,35.7200736],[139.2116933,35.7199787],[139.2117627,35.7198909],[139.2118151,35.719818],[139.2118552,35.7197249],[139.2118524,35.7196491],[139.2118258,35.7195415],[139.2119341,35.7194355],[139.2119898,35.7193587],[139.2120867,35.7193173],[139.2122447,35.7193247],[139.2124077,35.7193719],[139.212562,35.7193957],[139.2126706,35.7193935],[139.2127929,35.7193719],[139.2128937,35.7193506],[139.2130024,35.7192864],[139.2131229,35.7192112],[139.2132348,35.7191414],[139.2133429,35.7190263],[139.213507,35.7188978],[139.2136116,35.7188324],[139.2137286,35.7187943],[139.2138643,35.7187528],[139.2139968,35.7187242],[139.2141237,35.7187026],[139.2142854,35.7186463],[139.2143311,35.718591]]}'), 4326)
from roads r, administrators a
where r.name = '坂沢線' and a.name = '東京都森林事務所 秋川林務出張所';

-- 確認：この林道の区間と規制の数
select s.note as 区間, count(x.id) as 規制数
from segments s join roads r on r.id = s.road_id left join restrictions x on x.segment_id = s.id
where r.name = '坂沢線' group by s.id, s.note order by s.id;
